extends SceneTree
## Probe (task 63 terrain): cost in plain GDScript of (A) naive surface nets over one 16^3-cell chunk with a
## crater-like surface and per-cell material byte, vs (B) the heightfield patch vertex pass (33x33 with 8 neighbour sums,
## like DigView._rebuild). Native headless numbers: the web build is slower by an unknown factor.
const C := 16
func _init() -> void:
	var n := C + 1
	var d := PackedFloat32Array(); d.resize(n * n * n)
	var m := PackedByteArray(); m.resize(n * n * n)
	for z in n:
		for y in n:
			for x in n:
				var h := 8.0 + 2.0 * sin(x * 0.4) * cos(z * 0.35) - 3.0 * exp(-((x - 8) * (x - 8) + (z - 8) * (z - 8)) / 18.0)
				d[(z * n + y) * n + x] = h - y          # >0 solid
				m[(z * n + y) * n + x] = 0 if y < 4 else (1 if y < 7 else 2)
	var times := []
	var tris := 0
	for r in 20:
		var t0 := Time.get_ticks_usec()
		var vid := {}
		var verts := PackedVector3Array()
		var mats := PackedByteArray()
		var idx := PackedInt32Array()
		for z in C:
			for y in C:
				for x in C:
					var o := (z * n + y) * n + x
					var s := 0
					var c := [d[o], d[o + 1], d[o + n], d[o + n + 1], d[o + n * n], d[o + n * n + 1], d[o + n * n + n], d[o + n * n + n + 1]]
					for k in 8:
						if c[k] > 0.0:
							s += 1
					if s == 0 or s == 8:
						continue
					# vertex = mean of edge crossings (12 edges)
					var acc := Vector3.ZERO
					var cnt := 0
					for e in [[0,1],[2,3],[4,5],[6,7],[0,2],[1,3],[4,6],[5,7],[0,4],[1,5],[2,6],[3,7]]:
						var a: float = c[e[0]]
						var b: float = c[e[1]]
						if (a > 0.0) != (b > 0.0):
							var t := a / (a - b)
							var pa := Vector3(e[0] & 1, (e[0] >> 1) & 1, (e[0] >> 2) & 1)
							var pb := Vector3(e[1] & 1, (e[1] >> 1) & 1, (e[1] >> 2) & 1)
							acc += pa.lerp(pb, t)
							cnt += 1
					vid[o] = verts.size()
					verts.append(Vector3(x, y, z) + acc / cnt)
					mats.append(m[o])
		for k in vid.keys​():
			var o: int = k
			var x := o % n
			var y := (o / n) % n
			var z := o / (n * n)
			if x > 0 and y > 0 and vid.has(o - 1) and vid.has(o - n) and vid.has(o - n - 1):
				idx.append_array([vid[o], vid[o - 1], vid[o - n - 1], vid[o], vid[o - n - 1], vid[o - n]])
			if z > 0 and y > 0 and vid.has(o - n * n) and vid.has(o - n) and vid.has(o - n * n - n):
				idx.append_array([vid[o], vid[o - n * n], vid[o - n * n - n], vid[o], vid[o - n * n - n], vid[o - n]])
		var mesh := ArrayMesh.new()
		var arr := []; arr.resize(Mesh.ARRAY_MAX)
		arr[Mesh.ARRAY_VERTEX] = verts
		arr[Mesh.ARRAY_INDEX] = idx
		if idx.size() > 0:
			mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
		times.append((Time.get_ticks_usec() - t0) / 1000.0)
		tris = idx.size() / 3
	times.sort()
	print("PROBE_NETS chunk=%d^3 cells, surface verts+idx -> tris=%d, ms median=%.2f min=%.2f max=%.2f" % [C, tris, times[10], times[0], times[19]])
	# B: heightfield patch vertex pass like DigView._rebuild (33x33, 8-ring cavity sums, normals)
	var N := 32; var n1 := N + 1; var B := 4; var l := n1 + 2 * B
	var off := PackedInt32Array(); off.resize(l * l)
	for i in l * l:
		off[i] = int(300.0 * sin(i * 0.013))
	var tb := []
	for r in 20:
		var t0 := Time.get_ticks_usec()
		var verts := PackedVector3Array(); verts.resize(n1 * n1)
		var norms := PackedVector3Array(); norms.resize(n1 * n1)
		var cols := PackedColorArray(); cols.resize(n1 * n1)
		for lj in n1:
			for li in n1:
				var v := lj * n1 + li
				var s := (lj + B) * l + li + B
				var o := off[s]
				verts[v] = Vector3(li * 0.125, o * 0.001, lj * 0.125)
				norms[v] = Vector3(-(off[s + 1] - off[s - 1]) * 0.004, 1.0, -(off[s + l] - off[s - l]) * 0.004).normalized()
				var ring := off[s - B] + off[s + B] + off[s - B * l] + off[s + B * l] + off[s - B * l - B] + off[s - B * l + B] + off[s + B * l - B] + off[s + B * l + B]
				cols[v] = Color(1.0, 0.0, 0.5 + 0.5 * clampf((ring * 0.125 - o) / 300.0, -1.0, 1.0), 0.0)
		tb.append((Time.get_ticks_usec() - t0) / 1000.0)
	tb.sort()
	print("PROBE_HF patch 33x33 vertex pass ms median=%.2f min=%.2f max=%.2f" % [tb[10], tb[0], tb[19]])
	quit()
EOF
